from cryptography.hazmat.primitives.asymmetric import ec, ed25519, rsa


def describe(key) -> str:
    # Quanta could not see which algorithm this key uses. Check it where it is loaded.
    if isinstance(key, (rsa.RSAPrivateKey, rsa.RSAPublicKey)):
        return "RSA: quantum-vulnerable, see the signature or encryption guide"
    if isinstance(key, (ec.EllipticCurvePrivateKey, ec.EllipticCurvePublicKey)):
        return "Elliptic curve: quantum-vulnerable, see the signature or key exchange guide"
    if isinstance(key, (ed25519.Ed25519PrivateKey, ed25519.Ed25519PublicKey)):
        return "Ed25519: quantum-vulnerable, see the signature guide"
    return type(key).__name__


assert describe(ed25519.Ed25519PrivateKey.generate()).startswith("Ed25519")
